import { MakeLogicType, afterMount, kea, key, path, props } from 'kea'
import { loaders } from 'kea-loaders'

import { ApiConfig } from 'lib/api'

import { tracingSpansStoredTraceRetrieve } from 'products/tracing/frontend/generated/api'

import { TraceViewLogicProps } from './traceViewLogic'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface traceDistributedTraceLogicValues {
    distributedTraceId: string | null
    distributedTraceIdLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface traceDistributedTraceLogicActions {
    loadDistributedTraceId: () => any
    loadDistributedTraceIdFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadDistributedTraceIdSuccess: (
        distributedTraceId: string | null,
        payload?: any
    ) => {
        distributedTraceId: string | null
        payload?: any
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface traceDistributedTraceLogicMeta {
    key: string
}

export type traceDistributedTraceLogicType = MakeLogicType<
    traceDistributedTraceLogicValues,
    traceDistributedTraceLogicActions,
    TraceViewLogicProps,
    traceDistributedTraceLogicMeta
>

export const traceDistributedTraceLogic = kea<traceDistributedTraceLogicType>([
    path((key) => ['products', 'ai_observability', 'frontend', 'redesign', 'trace', 'traceDistributedTraceLogic', key]),
    props({} as TraceViewLogicProps),
    key((props) => props.traceId),
    loaders(({ props }) => ({
        // Null until the server names a trace in Tracing that holds spans, so the link never opens an empty trace.
        distributedTraceId: [
            null as string | null,
            {
                loadDistributedTraceId: async (): Promise<string | null> => {
                    const { traceId } = await tracingSpansStoredTraceRetrieve(String(ApiConfig.getCurrentProjectId()), {
                        trace_id: props.traceId,
                    })
                    return traceId
                },
            },
        ],
    })),
    afterMount(({ actions }) => actions.loadDistributedTraceId()),
])
